CustomField.formula:
IF(
  NPS_Score__c >= 9, "Promoter",
      IF(
          NPS_Score__c >= 7, "Neutral",
                IF(
                      NPS_Score__c  >= 0, "Detractor",
                             IF (
                                  NPS_Score__c = Null, "Not Scored",
                       NULL
             )

         )
     )
)
